SELECT l.store_id, l.sync_type, l.success, l.start_time, l.message FROM ecom_sync_log l JOIN (SELECT MAX(id) AS id FROM ecom_sync_log
store_id IN #{id}
GROUP BY store_id, sync_type) x ON x.id = l.id
